DIRS = ((1, 0), (-1, 0), (0, 1), (0, -1))


def cell(g, r, k):
    """Off-board reads as '@': it blocks a landing but is NOT counted as a neighbour."""
    return g[r][k] if 0 <= r < len(g) and 0 <= k < len(g[0]) else '@'


def step(g, r, k):
    """Number of orthogonal neighbours holding a piece; the rim is not a neighbour."""
    H = len(g); W = len(g[0]); n = 0
    if r and g[r - 1][k] != '.':
        n += 1
    if r + 1 < H and g[r + 1][k] != '.':
        n += 1
    if k and g[r][k - 1] != '.':
        n += 1
    if k + 1 < W and g[r][k + 1] != '.':
        n += 1
    return n


def legal(g, ch):
    H = len(g); W = len(g[0]); out = []
    for r in range(H):
        for k in range(W):
            if g[r][k] != ch:
                continue
            n = step(g, r, k)
            if not n:
                continue
            for i, j in DIRS:
                a, b = r + n * i, k + n * j
                if 0 <= a < H and 0 <= b < W and g[a][b] == '.':
                    out.append((r, k, a, b))
    return out


def stuck(g):
    """True when no 'x' has a legal move (early exit)."""
    H = len(g); W = len(g[0])
    for r in range(H):
        for k in range(W):
            if g[r][k] != 'x':
                continue
            n = step(g, r, k)
            if not n:
                continue
            for i, j in DIRS:
                a, b = r + n * i, k + n * j
                if 0 <= a < H and 0 <= b < W and g[a][b] == '.':
                    return False
    return True


def play(g, m):
    r, k, a, b = m
    h = [row[:] for row in g]
    h[a][b] = h[r][k]; h[r][k] = '.'
    return h


def between(g, m):
    a, b, d, e = m
    L = abs(d - a) + abs(e - b)
    i = (d - a) // L; j = (e - b) // L
    return [g[a + t * i][b + t * j] for t in range(1, L)]


def settled(rr, H, W, no, nx, nw):
    """A random position in which no 'x' has a legal move (blocks added to repair)."""
    g = [['.'] * W for _ in range(H)]
    cells = [(r, c) for r in range(H) for c in range(W)]
    rr.shuffle(cells)
    it = iter(cells)
    for ch, cnt in (('x', nx), ('o', no), ('#', nw)):
        for _ in range(cnt):
            r, c = next(it); g[r][c] = ch
    for _ in range(8):
        M = legal(g, 'x')
        if not M:
            return g
        r, k, a, b = rr.choice(M)
        g[a][b] = '#'
    return None


def check(G, m, minm):
    """Every invariant a shipped clue must satisfy. Returns (legal moves, 'flies over
    empty ground' subset) or None. Cheap tests first; the unique-winner scan exits at the
    first rival winner."""
    M = legal(G, 'o')
    if m not in M or len(M) < minm or stuck(G):
        return None
    E = [q for q in M if '.' in between(G, q)]
    if m not in E:
        return None
    H = len(G); W = len(G[0])
    X = [(r, c) for r in range(H) for c in range(W) if G[r][c] == 'x']
    ln = lambda q: abs(q[0] - q[2]) + abs(q[1] - q[3])
    dx = lambda r, c: min(abs(r - a) + abs(c - b) for a, b in X)
    if len([q for q in M if ln(q) >= ln(m)]) < 3:
        return None
    if len([q for q in M if dx(q[2], q[3]) <= dx(m[2], m[3])]) < 2:
        return None
    if dx(m[2], m[3]) == 1 and len([q for q in M if dx(q[2], q[3]) == 1]) < 2:
        return None
    B = [q for q in M if any(cell(G, q[0] + i, q[1] + j) == 'x' for i, j in DIRS)]
    if m in B and len(B) < 2:
        return None
    wins = 0
    for q in M:
        r, k, a, b = q
        G[a][b] = G[r][k]; G[r][k] = '.'
        won = stuck(G)
        G[r][k] = G[a][b]; G[a][b] = '.'
        if won:
            if q != m:
                return None
            wins += 1
    if wins != 1:
        return None
    return M, E


def build(rr, H, W, nt, mode):
    """Reverse move: take a settled position, un-move an 'o' by n squares and pad the
    origin with blocks until its neighbour count is exactly n."""
    F = settled(rr, H, W, rr.randint(3, 5), rr.randint(2, 4), rr.randint(1, 3))
    if not F:
        return []
    cand = []
    for d in range(H):
        for e in range(W):
            if F[d][e] != 'o':
                continue
            for i, j in DIRS:
                for n in (range(2, 6) if nt is None else (nt,)):
                    a, b = d - n * i, e - n * j
                    if not (0 <= a < H and 0 <= b < W) or F[a][b] != '.':
                        continue
                    G = [row[:] for row in F]
                    G[a][b] = 'o'; G[d][e] = '.'
                    k = step(G, a, b)
                    if k > n:
                        continue
                    if k < n:
                        room = [(a + u, b + v) for u, v in DIRS
                                if 0 <= a + u < H and 0 <= b + v < W
                                and G[a + u][b + v] == '.' and (a + u, b + v) != (d, e)]
                        if len(room) < n - k:
                            continue
                        rr.shuffle(room)
                        for (r, c) in room[:n - k]:
                            G[r][c] = '#'
                        if step(G, a, b) != n:
                            continue
                    bt = between(G, (a, b, d, e))
                    if '.' not in bt:
                        continue
                    if mode == 'mixed' and all(ch == '.' for ch in bt):
                        continue
                    if mode == 'clear' and any(ch != '.' for ch in bt):
                        continue
                    cand.append((G, (a, b, d, e)))
    rr.shuffle(cand)
    return cand[:24]


def grow(rr, G, m, M, E, minm, mine, H, W):
    """Add pieces (never touching the answer) so that several *other* legal moves also
    fly over empty ground - otherwise 'the one that leaps over a gap' would be a free
    answer."""
    for _ in range(5):
        if len(E) >= mine:
            break
        empt = [(r, c) for r in range(H) for c in range(W)
                if G[r][c] == '.' and (r, c) != (m[2], m[3])
                and any(cell(G, r + i, c + j) in 'ox#' for i, j in DIRS)]
        rr.shuffle(empt)
        grew = False
        for (r, c) in empt[:9]:
            for ch in ('#', 'o'):
                G2 = [row[:] for row in G]
                G2[r][c] = ch
                ck = check(G2, m, minm)
                if ck and len(ck[1]) > len(E):
                    G, M, E = G2, ck[0], ck[1]
                    grew = True
                    break
            if grew:
                break
        if not grew:
            break
    return G, M, E


def generate(seed):
    rr = random.Random(seed)
    H, W = rr.choice([(6, 6), (6, 6), (6, 6), (5, 6), (6, 5), (5, 5)])
    nt = rr.choice([2, 2, 3, 3, 3])
    mode = rr.choice(['clear', 'mixed']) if nt > 2 else 'clear'
    best = None
    for tn, tm, minm, mine, tries in ((nt, mode, 7, 5, 25), (nt, None, 7, 5, 25),
                                      (None, None, 7, 5, 30), (None, None, 6, 2, 50)):
        for _ in range(tries):
            for G, m in build(rr, H, W, tn, tm):
                ck = check(G, m, minm)
                if not ck:
                    continue
                G, M, E = grow(rr, G, m, ck[0], ck[1], minm, mine, H, W)
                if best is None or len(E) > len(best[1]):
                    best = (G, E)
                if len(E) >= mine:
                    return "\n".join("".join(row) for row in G)
        if best and len(best[1]) >= 4:
            break
    return "\n".join("".join(row) for row in best[0])

